DROP TABLE IF EXISTS `transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `transactions` (
  `id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` enum('sale','credit') COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount` double(8,2) NOT NULL,
  `refunded_amount` double(8,2) NOT NULL,
  `currency` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('authorization_expired','authorized','settlement_pending','settlement_declined','failed','gateway_rejected','processor_declined','settled','settling','submitted_for_settlement','voided') COLLATE utf8mb4_unicode_ci NOT NULL,
